/* ======== from app_types.h ======== */
/*
 * app_types.h  --  SHARED HEADER (Buddy 4 maintains the ESTOP_REQ + IMU sections)
 *
 * Every width below is a PLACEHOLDER until the real ranges are measured/agreed
 * by the team. Anything sent over MQTT must use explicit masks/shifts (below),
 * never compiler bit-fields.
 */
#ifndef APP_TYPES_H
#define APP_TYPES_H

#include <stdint.h>
#include <stdbool.h>

/* All encodings (enums, flag bits, widths) are GENERATED into app_fields.h from
 * tools/gen_data_repr.py: ESTOP_SRC_*, SYSFAULT_*, IMU_EVT_*, MOTION_*, IMU_FAULT_*, LIFT_CAUSE_*, IMU_ST_*.
 * ESTOP_REQ rules: each source sets ONLY its own bit; Motion Control reads the flag before every
 * PWM write; only the Vehicle Controller clears bits. The IMU never clears them and never writes PWM. */
#define IMU_FAULT_BLOCKING    (IMU_FAULT_NACK | IMU_FAULT_STALE | IMU_FAULT_BUS_STUCK | \
                               IMU_FAULT_CAL_FAIL | IMU_FAULT_TIMING)

/* ---------- 32-bit imu_evt_q message ----------
 * [31:16] timestamp (ms, low 16 bits, wraps every 65.5 s)
 * [15:9]  spare
 * [8:2]   payload (7 bits)
 * [1:0]   event type                                                            */
#define IMU_MSG_PACK(type, payload, ts16) \
    ((uint32_t)(((uint32_t)(type) & 0x3u) | (((uint32_t)(payload) & 0x7Fu) << 2) | \
                (((uint32_t)(ts16) & 0xFFFFu) << 16)))
#define IMU_MSG_TYPE(m)      ((uint32_t)(m) & 0x3u)
#define IMU_MSG_PAYLOAD(m)   (((uint32_t)(m) >> 2) & 0x7Fu)
#define IMU_MSG_TS16(m)      (((uint32_t)(m) >> 16) & 0xFFFFu)

/* ---------- Motion Control snapshot word (single writer = Motion Control) ----------
 * One aligned 32-bit store/load, so the IMU never sees a torn speed/distance pair.
 * [9:0] speed mm/s   [25:10] distance mm (wraps)   [31:26] sequence count
 * Ranges are placeholders; Buddy 2 confirms.                                       */
#define MC_SNAP_PACK(speed, dist, seq) \
    ((uint32_t)(((uint32_t)(speed) & 0x3FFu) | (((uint32_t)(dist) & 0xFFFFu) << 10) | \
                (((uint32_t)(seq) & 0x3Fu) << 26)))
#define MC_SNAP_SPEED(w)  ((uint16_t)((uint32_t)(w) & 0x3FFu))
#define MC_SNAP_DIST(w)   ((uint16_t)(((uint32_t)(w) >> 10) & 0xFFFFu))
#define MC_SNAP_SEQ(w)    ((uint8_t)(((uint32_t)(w) >> 26) & 0x3Fu))

#endif /* APP_TYPES_H */

/* ======== from imu_cfg.h ======== */
/*
 * imu_cfg.h -- IMU tunables.
 * EVERY NUMBER HERE IS A PLACEHOLDER until tuned from logged data (A7, A8, A12).
 * Sensor: LSM303D (the GY-511 on Buddy 5's car; WHO_AM_I 0x0F reads 0x49). Accelerometer AND magnetometer
 * share one address, 0x1D (SA0 high). The older LSM303DLHC GY-511 answers at 0x19 and uses different
 * control registers, so this driver does not run on it unchanged.
 * VERIFY against your board's datasheet before trusting any of this.
 */
#ifndef IMU_CFG_H
#define IMU_CFG_H

/* ---- sensor ---- */
#define IMU_I2C_ADDR_ACCEL        0x1D     /* LSM303D, SA0 high (was 0x19 for the LSM303DLHC) */
#define IMU_POLL_PERIOD_US        10000
#define IMU_SENS_MG_PER_LSB       4.0f     /* +-8 g. The LSM303D is really 3.904 mg/count (readings ~2.5% high);
                                              calibration absorbs it. Use 3.904f for exact values. */
#define IMU_RAW_FULLSCALE         2047
/* Mounting. Which sensor axis (0=X, 1=Y, 2=Z) is the car's forward / lateral / up axis,
 * and the sign that makes each point the right way:
 *   forward axis: reads POSITIVE when the car pushes forward (accelerating)
 *   up axis     : reads POSITIVE (~ +1 g) when the car sits level
 * Use the bring-up firmware's 'p' command to check these (see README). */
#define IMU_AXIS_FWD   0
#define IMU_AXIS_LAT   1
#define IMU_AXIS_UP    2
/* Buddy 5's car: the IMU is mounted upside down and facing backwards, so
 *   fwd = -X, lat = +Y, up = -Z.
 * LAT is not yet verified on the car (lift the right side: lat should go negative).
 * The #ifndef lets the PC tests override these with -D (their fake sensor uses a +X/+Y/+Z mounting). */
#ifndef IMU_SIGN_FWD
#define IMU_SIGN_FWD   (-1.0f)
#endif
#ifndef IMU_SIGN_LAT
#define IMU_SIGN_LAT   (1.0f)
#endif
#ifndef IMU_SIGN_UP
#define IMU_SIGN_UP    (-1.0f)
#endif
/* Flip to -1 if a nose-UP tilt reports a NEGATIVE pitch. */
#define IMU_PITCH_SIGN 1.0f

/* ---- calibration (car must be stopped) ---- */
#define CAL_SAMPLES               50
#define CAL_NOISE_MAX_MG          60.0f
#define CAL_MAX_RETRIES           3

/* ---- fault detection ---- */
#define NACK_POLLS_TO_FAULT       2        /* 2 x 10 ms                               */
#define STALE_POLLS_TO_FAULT      3        /* 3 x 10 ms = 30 ms (NFR15 proposal)      */
#define SAT_POLLS_TO_FLAG         2
#define GOOD_READS_TO_RECOVER     3
#define LATE_POLL_US              3000
#define LATE_POLLS_TO_FAULT       10
/* Team decision pending: should an IMU sensor fault stop the car? 1 = yes. */
#define IMU_FAULT_TRIGGERS_ESTOP  1

/* ---- lifted / overturned (16 Nov; replaces the impact voting) ----
 * The requirement changed (11 Nov): no collision detection; the IMU has to
 * notice the car being LIFTED or OVERTURNED, and the motors stop at once.
 * Lifting the car ends the run in the demonstration.
 *   UP   : the car moves upwards.  The acceleration along "up" (gravity as
 *          calibrated) minus 1 g is summed to an upward speed, which fades
 *          again within LIFT_V_TAU_S.  A hump lifts the car at a few mm/s;
 *          a hand at some hundred.
 *   TILT : gravity points somewhere else than when calibrated: tipped
 *          sideways by LIFT_ROLL_DEG (a hump tips the car nose up, never
 *          sideways), or by LIFT_TILT_DEG in any direction (on its side,
 *          upside down).
 * PLACEHOLDERS until tried on the car: lift it 10 times from a patrol
 * (S4-M04) and drive 10 humps (S4-M05). */
#define LIFT_UP_MM_S              150.0f   /* upward speed that means "lifted".  Lower =
                                              a slower lift is noticed, but vibration may
                                              stop the car: watch "S4: upward speed peak"
                                              on the console while it drives and keep
                                              this at least 3 x that                   */
#define LIFT_UP_POLLS             3        /* ... for this many polls (x 10 ms)        */
#define LIFT_V_TAU_S              0.7f     /* the summed speed fades with this time    */
#define LIFT_V_FLOOR_MM_S         50.0f    /* never below minus this (on a slope "up"
                                              reads low; it must not hide a lift)      */
#define LIFT_TILT_DEG             35.0f    /* tipped this far in any direction ...     */
#define LIFT_ROLL_DEG             20.0f    /* ... or this far sideways                 */
#define LIFT_TILT_POLLS           20       /* ... for this many polls (200 ms)         */
#define LIFT_LPF_ALPHA            0.2f     /* smoothing of gravity's direction         */
#define LIFT_REARM_POLLS          100      /* level and still again this long (1 s):
                                              ready for the next lift                  */
#define LIFT_REPORT_S             10       /* console: the largest upward speed seen, every
                                              this many seconds (for tuning; 0 = off)  */

/* ---- hump (pitch x encoder distance) ---- */
#define HUMP_PITCH_ENTER_RAD      0.044f   /* 2.5 deg from the baseline, nose up or down or
                                              sideways (20 Nov: was 2; driving on the flat
                                              tips the car 1-1.5 deg; 19 Nov: was 4) */
#define HUMP_PITCH_EXIT_RAD       0.026f   /* 1.5 deg: back at the baseline (20 Nov: was 1) */
#define HUMP_END_POLLS            3
#define HUMP_MIN_SPEED            10       /* mm/s (80 -> 40 -> 10): must stay below the
                                              patrol speed (20 mm/s since 2 Nov), or humps
                                              are never measured */
#define HUMP_ABORT_STALL_POLLS    20       /* not used since 20 Nov (a stop on the hump only pauses it) */
#define HUMP_MIN_HEIGHT_MM        0.0f     /* 20 Nov: no smallest height, every hump is
                                              reported (was 2.0; 19 Nov: was 3.0)     */
#define HUMP_CALM_MM              20.0f    /* 20 Nov: back at the baseline for this much
                                              driving = the hump is over               */
#define HUMP_MAX_LEN_MM           1000.0f  /* 20 Nov: a hump ends after this much driving
                                              anyway                                   */
#define HUMP_GAIN                 1.0f     /* fit from calibration passes (A7)        */
#define HUMP_TRACK_MM             120.0f   /* 20 Nov: a hump under one wheel tips the car
                                              sideways: height = track x sin(roll)
                                              (TRACK_WIDTH_MM, subsystem2.h)          */
#define PITCH_LPF_ALPHA           0.1f     /* 20 Nov: was 0.3 (about 30 ms; now about 100 ms,
                                              smooths the jolts, a hump takes ~1 s)    */

/* ---- Motion Control snapshot health ---- */
#define SNAP_STALE_POLLS          5        /* sequence unchanged this long = Motion Control not updating */
#define SNAP_DS_SAFETY_MULT       4        /* a distance jump bigger than this x expected is a discontinuity */

/* ---- debug read-out (bring-up build only; keep 0 in the kernel build) ---- */
#ifndef IMU_ENABLE_DEBUG
#define IMU_ENABLE_DEBUG          0
#endif

/* ---- motion classification ---- */
#define MOTION_STOP_SPEED         10       /* mm/s (was 20: below the 20 mm/s patrol) */
#define MOTION_STOP_POLLS         5
#define MOTION_TURN_LAT_MG        250.0f
#define MOTION_ACCEL_FWD_MG       150.0f
#define MOTION_ACCEL_DSPEED       8        /* mm/s gained per poll                    */
#define MOTION_DEBOUNCE_POLLS     3

#endif /* IMU_CFG_H */

/* ======== from imu.h ======== */
#ifndef IMU_H
#define IMU_H

#include <stdint.h>
#include <stdbool.h>

/* Diagnostic counters (saturating, not application data). */
typedef struct {
    uint16_t polls, lifts, humps, drops, resets, reset_rejected;   /* lifts: 16 Nov, was impacts / single_votes */
    uint16_t snap_stale, ds_jumps;
    int16_t  up_peak_mm_s;    /* largest upward speed (lift detection) since imu_take_up_peak() */
    int16_t  pitch_max_x10, pitch_min_x10;  /* 19 Nov: pitch while moving, 0.1 deg, since imu_take_pitch_peaks() */
} imu_stats_t;

void        imu_init(void);
void        imu_step(uint32_t late_us);   /* one poll cycle (called by imu_run, or by tests) */
void        imu_run(void);                /* task body: never returns                        */
imu_state_t imu_get_state(void);
uint8_t     imu_get_fault_mask(void);
int16_t     imu_take_up_peak(void);       /* returns it and starts again from 0 (tuning aid) */
void        imu_take_pitch_peaks(int16_t *p_max_x10, int16_t *p_min_x10);  /* same for the pitch (hump tuning) */
imu_stats_t imu_get_stats(void);

#if IMU_ENABLE_DEBUG
typedef struct {
    float    body_mg[3];      /* forward, lateral, up (mg)            */
    float    a_dev_mg;        /* |a| - 1 g                            */
    float    pitch_rad;       /* filtered pitch, relative to baseline */
    uint8_t  lift;            /* LIFT_CAUSE_* reported this poll      */
    float    up_mm_s;         /* summed upward speed (lift detection) */
    bool     hump_active;
    float    hump_mm;         /* running height integral (gain applied) */
    uint16_t speed_mm_s;
} imu_debug_t;
imu_debug_t imu_get_debug(void);
#endif

#endif /* IMU_H */

/* ======== from imu_logic.h ======== */
/*
 * imu_logic.h -- pure logic (no hardware, no kernel calls). Compiles and tests on a PC.
 *   - fault detection / recovery        - lifted / overturned detection
 *   - hump height (pitch x distance)    - motion classification
 * State is bit-packed per the minimum-bit requirement; widths are tied to the tuning
 * constants by _Static_assert in imu_logic.c, so changing a threshold cannot silently overflow a field.
 */
#ifndef IMU_LOGIC_H
#define IMU_LOGIC_H

#include <stdint.h>
#include <stdbool.h>

typedef struct { int16_t x, y, z; bool fresh; } raw3_t;          /* 12-bit, right-aligned */
typedef enum { RD_OK = 0, RD_NACK, RD_TIMEOUT } read_result_t;

/* ---------------- faults (19 bits) ---------------- */
typedef struct {
    unsigned mask      : 7;     /* IMU_FAULT_* bits   */
    unsigned nack_run  : 2;
    unsigned stale_run : 2;
    unsigned sat_run   : 2;
    unsigned good_run  : 2;
    unsigned late_run  : 4;
} fault_t;

void fault_init(fault_t *f);
/* raw may be NULL (sensor-init failures). Returns true if a BLOCKING fault is active. */
bool fault_on_read(fault_t *f, read_result_t r, const raw3_t *raw);
void fault_on_lateness(fault_t *f, uint32_t late_us);
void fault_set_cal_fail(fault_t *f);
void fault_note_queue(fault_t *f, bool posted);
bool fault_recovered(const fault_t *f);
void fault_clear_blocking(fault_t *f);

/* ---------------- lifted / overturned (16 Nov; replaces the 2-of-3 impact voting) ----------------
 * LIFT_CAUSE_UP   : the car moves upwards faster than LIFT_UP_MM_S (acceleration along the calibrated
 *                   "up", minus 1 g, summed to a speed that fades within LIFT_V_TAU_S)
 * LIFT_CAUSE_TILT : gravity's direction (smoothed) is LIFT_ROLL_DEG sideways, or LIFT_TILT_DEG in any
 *                   direction, away from the calibrated one for LIFT_TILT_POLLS
 * Driving does neither: a hump raises the car at a few mm/s and tips it nose up by a few degrees,
 * never sideways; vibration averages out.  Once it fires it stays quiet until the car has been level
 * and still for LIFT_REARM_POLLS (one event for one lift). */
typedef struct {
    float    f[3];            /* smoothed acceleration, body frame (mg)        */
    float    v_mm_s;          /* upward speed (summed, fading)                 */
    unsigned up_run   : 2;
    unsigned tilt_run : 5;
    unsigned calm_run : 7;
    unsigned fired    : 1;    /* reported; waiting for level and still again   */
    unsigned seeded   : 1;
} lift_t;

void    lift_init(lift_t *l);
/* a_mg: this poll's acceleration, body frame (forward, lateral, up); base_mg / g_mg: the calibrated
 * gravity vector and its length.  Returns LIFT_CAUSE_* once when the car is lifted or tipped over,
 * else 0. */
uint8_t lift_step(lift_t *l, const float a_mg[3], const float base_mg[3], float g_mg);

/* ---------------- hump (8 bits of state + two floats) ---------------- */
typedef struct { float h_mm, h_max_mm, roll_max, len_mm, calm_mm; unsigned active : 1; unsigned stall : 5; } hump_t;
void  hump_init(hump_t *h);
float pitch_from_accel(float ax_mg, float ay_mg, float az_mg);
float roll_from_accel(float ax_mg, float ay_mg, float az_mg);   /* 20 Nov */
/* Returns true when a hump completes; *height_x2 = height in 0.5 mm steps (0..127, 127 = overrange).
 * 20 Nov: pitch and roll are measured from the level at RESET (calibration), the baseline; a tilt
 * away from it (nose up or down, or sideways: one wheel on the hump) starts a hump, back at it for
 * HUMP_CALM_MM ends it; the height is the larger of pitch x distance and HUMP_TRACK_MM x sin(largest
 * roll). */
bool  hump_step(hump_t *h, float pitch_rad, float roll_rad, uint16_t ds_mm, bool moving,
                float gain, uint8_t *height_x2);

/* ---------------- motion (9 bits) ---------------- */
typedef struct { unsigned stopped_run : 3; unsigned cand_run : 2; unsigned cand : 2; unsigned cur : 2; } motion_t;
void motion_init(motion_t *m);
/* Returns true when the (debounced) class changes; *out holds the new class. */
bool motion_step(motion_t *m, float fwd_mg, float lat_mg, uint16_t speed,
                 uint16_t prev_speed, motion_class_t *out);

#endif /* IMU_LOGIC_H */

